der_date) END AS adjusted_order_date, COALESCE(CAST(cf.pickup_date AS TIMESTAMP), CAST(a.dispatch_date AS TIMESTAMP)) AS Order_Manifest_date, COALESCE(CAST(cf.current_Date AS TIMESTAMP), CAST(shipping_last_update_date AS TIMESTAMP)) AS Order_Shipping_Last_Update_Date, CAST(a.delivered_date AS TIMESTAMP) AS order_delivered_date, UPPER(COALESCE(cf.current_status, a.shipping_status)) AS shipping_status, UPPER(a.order_status) AS order_status, coalesce(cm.mapped_courier_name, a.courier) AS COURIER, cm.courier_group AS COURIER_Partner, COALESCE(cf.Payment_method, a.payment_mode) AS payment_mode, UPPER(CASE WHEN LOWER(order_status) LIKE \'%cancel%\' OR LOWER(oms_order_status) LIKE \'%cancel%\' OR LOWER(final_shipping_status) LIKE \'%cancel%\' OR LOWER(cf.current_status) LIKE \'%cancel%\' THEN \'CANCELLED\' ELSE COALESCE(CASE WHEN LOWER(CURRENT_STATUS) LIKE \'deliver%\' THEN \'DELIVERED\' ELSE NULL END, FINAL_SHIPPING_STATUS, shipping_status, order_status) END) AS final_status, TAT.ZONE, MAX(TARGET_TAT) AS s2d_sla, MAX(TARGET_TAT2) AS o2s_sla, MAX(TARGET_TAT1) AS o2d_sla, MAX(TAT.TARGET_TAT) AS TARGET_TAT, DATEADD(day, CAST(MAX(TARGET_TAT1) AS INTEGER), CAST(order_date AS DATE)) AS promised_delivery_date FROM public.quickshift_sales_consolidated a LEFT JOIN (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY awb ORDER BY current_Date DESC) AS rw FROM public.quickshift_CLICKPOST_FACT_ITEMS) WHERE rw=1 ) cf ON LOWER(cf.awb) = LOWER(a.awb) LEFT JOIN public.quickshift_marketplace_fulfilment_cutoff b ON LOWER(b.marketplace) = LOWER(a.marketplace) LEFT JOIN (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY pickup_pincode, destination_pincode ORDER BY 1) AS rw FROM public.quickshift_pincode_zone ) WHERE rw = 1 ) pincode ON a.source_pincode = pincode.pickup_pincode AND a.pincode = pincode.destination_pincode LEFT JOIN (SELECT * FROM (SELECT zone, Courier, S2d_sla, o2d_sla, S2d_SLA AS TARGET_TAT, O2d_SLA AS TARGET_TAT1, CAST(O2d_SLA AS INTEGER) - CAST(S2d_SLA AS INTEGER) AS TARGET_TAT2, ROW_NUMBER() OVER (PARTITION BY LOWER(zone), LOWER(courier) ORDER BY 1) AS rw FROM public.quickshift_zone_tat ) WHERE rw=1) TAT ON LOWER(pincode.zone) = LOWER(TAT.zone) AND LOWER(a.courier) = LOWER(TAT.courier) LEFT JOIN public.courier_mapping cm ON LOWER(COALESCE(cf.courier_partner, a.COURIER)) = LOWER(cm.courier) GROUP BY a.order_id, a.awb, a.reference_code, a.marketplace, a.source_pincode, a.pincode, a.warehouse, b.Same_Day_Cut_Off, a.order_date, a.Order_Time, COALESCE(CAST(cf.pickup_date AS TIMESTAMP), CAST(a.dispatch_date AS TIMESTAMP)), COALESCE(CAST(cf.current_Date AS TIMESTAMP), CAST(shipping_last_update_date AS TIMESTAMP)), COALESCE(CAST(cf.delivery_date AS TIMESTAMP), CAST(a.delivered_date AS TIMESTAMP)), UPPER(COALESCE(cf.current_status, shipping_status)), UPPER(a.order_status), a.courier, cm.mapped_courier_name, cm.courier_group, COALESCE(cf.Payment_method, a.payment_mode), TAT.ZONE, CAST(a.delivered_date AS TIMESTAMP), UPPER(CASE WHEN (LOWER(order_status) LIKE \'%cancel%\' OR LOWER(oms_order_status) LIKE \'%cancel%\' OR LOWER(final_shipping_status) LIKE \'%cancel%\' OR LOWER(cf.current_status) LIKE \'%cancel%\') THEN \'CANCELLED\' ELSE COALESCE((CASE WHEN LOWER(CURRENT_STATUS) LIKE \'deliver%\' THEN \'DELIVERED\' ELSE NULL END) ,FINAL_SHIPPING_STATUS,shipping_status,order_status) END) ), status_flags AS ( SELECT *, CASE WHEN final_status = \'DELIVERED\' THEN 1 ELSE 0 END AS delivered_order, CASE WHEN final_status = \'ORDER YET TO SYNC\' THEN 1 ELSE 0 END AS Order_yet_to_Sync_Order, CASE WHEN final_status = \'CONFIRMED\' THEN 1 ELSE 0 END AS Confirmed_Order, CASE WHEN final_status = \'ASSIGNED\' THEN 1 ELSE 0 END AS Assigned_Order, CASE WHEN final_status = \'OPEN\' THEN 1 ELSE 0 END AS Open_Order, CASE WHEN final_status = \'PRINTED\' THEN 1 ELSE 0 END AS Printed_Order, CASE WHEN final_status = \'PENDING\' THEN 1 ELSE 0 END AS Pending_Order, CASE WHEN final_status = \'IN TRANSIT\' THEN 1 ELSE 0 END AS In_Transit_order, CASE WHEN final_status = \'RTO\' THEN 1 ELSE 0 END AS RTO_Order, CASE WHEN final_status = \'RTS\' THEN 1 ELSE 0 END AS RTS_Order, CASE WHEN final_status = \'RETURNED\' THEN 1 ELSE 0 END AS Returned_order, CASE WHEN final_status = \'PICKUP ERROR\' THEN 1 ELSE 0 END AS Pickup_Error, CASE WHEN final_status = \'LOST\' THEN 1 ELSE 0 END AS Lost_Order, CASE WHEN final_status = \'EXCEPTION\' THEN 1 ELSE 0 END AS Exception_Order, CASE WHEN final_status = \'MISROUTED\' THEN 1 ELSE 0 END AS Misrouted_Order, CASE WHEN final_status = \'UNDERPROCESS\' THEN 1 ELSE 0 END AS Underprocess_Order, CASE WHEN final_status = \'DAMAGED\' THEN 1 ELSE 0 END AS Damaged_Order, CASE WHEN final_status = \'CANCELLED\' THEN 1 ELSE 0 END AS cancelled_order FROM base_data ), speeds AS ( SELECT *, CASE WHEN delivered_order = 1 THEN DATEDIFF(hour, status_flags.order_timestamp, ORDER_DELIVERED_DATE) ELSE DATEDIFF(hour, status_flags.order_timestamp, GETDATE()) END AS Time_From_Order, DATEDIFF(hour, CAST(status_flags.order_timestamp AS TIMESTAMP), CAST(order_manifest_date AS TIMESTAMP)) AS Dispatch_Speed, DATEDIFF(hour, CAST(status_flags.order_timestamp AS TIMESTAMP), CAST(ORDER_DELIVERED_DATE AS TIMESTAMP)) AS o2d_delivery_Speed, DATEDIFF(hour, CAST(order_manifest_date AS TIMESTAMP), CAST(ORDER_DELIVERED_DATE AS TIMESTAMP)) AS s2d_delivery_Speed, CASE WHEN delivered_order = 1 THEN DATEDIFF(hour, Order_Manifest_date, ORDER_DELIVERED_DATE) END AS Delivery_Speed, CASE WHEN delivered_order = 1 THEN DATEDIFF(hour, Order_Manifest_date, ORDER_DELIVERED_DATE) ELSE DATEDIFF(hour, Order_Manifest_date, GETDATE()) END AS deliver_time, CASE WHEN EXTRACT(HOUR FROM order_timestamp) < EXTRACT(HOUR FROM CAST(same_day_cut_off AS TIME)) THEN DATEDIFF( day, CAST(order_date AS TIMESTAMP), COALESCE(ORDER_MANIFEST_DATE, GETDATE()) ) ELSE DATEDIFF( day, CAST(order_date AS TIMESTAMP), COALESCE(ORDER_MANIFEST_DATE, GETDATE()) ) - 1 END AS Dispatch_Flag, CASE WHEN NOT LOWER(final_status) LIKE \'%cancel%\' THEN DATEDIFF ( hour, order_manifest_date, DATEADD( day, CAST(TARGET_TAT AS INTEGER) + 1, DATE_TRUNC(\'day\', order_manifest_date) ) ) END AS target_tat_hours, CASE WHEN NOT LOWER(final_status) LIKE \'%cancel%\' THEN DATEDIFF ( hour, order_manifest_date, COALESCE( order_delivered_date, GETDATE() ) ) END AS DELIVERY_TAT, CASE WHEN NOT LOWER(final_status) LIKE \'%cancel%\' THEN DATEDIFF( hour, order_timestamp, COALESCE( order_manifest_date, GETDATE() ) ) END AS DELIVERY_TAT_o2s, CASE WHEN NOT LOWER(final_status) LIKE \'%cancel%\' THEN DATEDIFF( hour, order_timestamp, DATEADD( day, CAST(o2d_sla AS INTEGER) + 1, DATE_TRUNC(\'day\', order_timestamp) ) ) END AS target_tat_hours_o2d, CASE WHEN NOT LOWER(final_status) LIKE \'%cancel%\' THEN DATEDIFF( hour, order_timestamp, COALESCE(order_delivered_date, GETDATE()) ) END AS DELIVERY_TAT_o2d FROM status_flags ), TIME_CATEGORIES AS ( SELECT *, CASE WHEN Time_From_Order <= 24 THEN \'1. <=24 hours\' WHEN Time_From_Order <= 48 THEN \'2. 25 - 48 hours\' WHEN Time_From_Order <= 72 THEN \'3. 49 - 72 hours\' WHEN Time_From_Order <= 96 THEN \'4. 73 - 96 hours\' WHEN Time_From_Order <= 120 THEN \'5. 97 - 120 hours\' ELSE \'6. >120 hours\' END AS TIME_FROM_ORDER_CATEGORY, CASE WHEN Dispatch_Speed <= 24 THEN \'1. <=24 hours\' WHEN Dispatch_Speed <= 48 THEN \'2. 25 - 48 hours\' WHEN Dispatch_Speed <= 72 THEN \'3. 49 - 72 hours\' WHEN Dispatch_Speed <= 96 THEN \'4. 73 - 96 hours\' WHEN Dispatch_Speed <= 120 THEN \'5. 97 - 120 hours\' WHEN Dispatch_Speed IS NOT NULL THEN \'6. >120 hours\' WHEN Dispatch_Speed IS NULL THEN \'NOT DISPATCHED\' END AS Dispatch_Speed_flag, CASE WHEN Dispatch_Flag = 0 THEN \'Same Day\' WHEN Dispatch_Flag = 1 THEN \'Next Day\' ELSE \'2+ Days\' END AS Final_Dispatch_Bucket, CASE WHEN Delivery_Speed <= 24 THEN \'1. <=24 hours\' WHEN Delivery_Speed <= 48 THEN \'2. 25 - 48 hours\' WHEN Delivery_Speed <= 72 THEN \'3. 49 - 72 hours\' WHEN Delivery_Speed <= 96 THEN \'4. 73 - 96 hours\' WHEN Delivery_Speed <= 120 THEN \'5. 97 - 120 hours\' WHEN Delivery_Speed > 120 THEN \'6. > 120 hours\' ELSE \'NOT DELIVERED\' END AS delivery_time_flag, CASE WHEN o2d_delivery_Speed <= 24 THEN \'1. <=24 hours\' WHEN o2d_delivery_Speed <= 48 THEN \'2. 25 - 48 hours\' WHEN o2d_delivery_Speed <= 72 THEN \'3. 49 - 72 hours\' WHEN o2d_delivery_Speed <= 96 THEN \'4. 73 - 96 hours\' WHEN o2d_delivery_Speed <= 120 THEN \'5. 97 - 120 hours\' WHEN o2d_delivery_Speed > 120 THEN \'6. > 120 hours\' ELSE \'NOT DELIVERED\' END AS delivery_time_flag_o2d, CASE WHEN LOWER(final_status) LIKE \'%cancel%\' THEN \'CANCELLED\' WHEN NOT (LOWER(final_status) LIKE \'%cancel%\') AND order_manifest_Date IS NULL THEN \'NOT DISPATCHED\' WHEN order_manifest_Date IS NOT NULL THEN \'DISPATCHED\' END AS dispatch_status, CASE WHEN DELIVERY_TAT <= target_tat_hours THEN \'ON TIME\' WHEN DELIVERY_TAT > target_tat_hours THEN \'DELAYED\' END AS TAT_PERFORMANCE, UPPER (CASE WHEN (NOT(LOWER(final_status) LIKE \'%cancel%\')) AND order_delivered_date IS NULL AND DELIVERY_TAT <= target_tat_hours THEN \'In Transit - On Time\' WHEN (NOT(LOWER(final_status) LIKE \'%cancel%\')) AND order_delivered_date IS NULL AND DELIVERY_TAT > target_tat_hours THEN \'In Transit - Delayed\' WHEN (NOT(LOWER(final_status) LIKE \'%cancel%\')) AND order_delivered_date IS NOT NULL AND DELIVERY_TAT > target_tat_hours THEN \'DELIVERED - Delayed\' WHEN (NOT(LOWER(final_status) LIKE \'%cancel%\')) AND order_delivered_date IS NOT NULL AND DELIVERY_TAT <= target_tat_hours THEN \'DELIVERED - On Time\' ELSE \'ZONE NOT MAPPED\' END) AS s2d_status, UPPER(CASE WHEN (NOT(LOWER(final_status) LIKE \'%cancel%\') AND order_manifest_date IS NULL) THEN \'NOT DISPATCHED\' WHEN (NOT(LOWER(final_status) LIKE \'%cancel%\') AND order_delivered_date IS NULL AND DELIVERY_TAT_o2d <= target_tat_hours_o2d) THEN \'IN TRANSIT ON TIME\' WHEN (NOT(LOWER(final_status) LIKE \'%cancel%\') AND order_delivered_date IS NULL AND DELIVERY_TAT_o2d > target_tat_hours_o2d) THEN \'IN TRANSIT DELAYED\' WHEN (NOT(LOWER(final_status) LIKE \'%cancel%\') AND order_delivered_date IS NOT NULL AND DELIVERY_TAT_o2d > target_tat_hours_o2d) THEN \'DELIVERED DELAYED\' WHEN (NOT(LOWER(final_status) LIKE \'%cancel%\') AND order_delivered_date IS NOT NULL AND DELIVERY_TAT_o2d <= target_tat_hours_o2d) THEN \'DELIVERED ON TIME\' ELSE \'ZONE NOT MAPPED\' END) AS o2d_status, UPPER(CASE WHEN ( (NOT (LOWER(final_status) LIKE \'%cancel%\')) AND order_manifest_date IS NULL AND COALESCE(order_manifest_date, GETDATE()) <= Target_dispatch ) THEN \'NOT DISPATCHED ON TIME\' WHEN ( (NOT (LOWER(final_status) LIKE \'%cancel%\')) AND order_manifest_date IS NULL AND COALESCE(order_manifest_date, GETDATE()) > Target_dispatch ) THEN \'NOT DISPATCHED DELAYED\' WHEN ( (NOT (LOWER(final_status) LIKE \'%cancel%\')) AND order_manifest_date IS NOT NULL AND COALESCE(order_manifest_date, GETDATE()) > Target_dispatch ) THEN \'DISPATCHED DELAYED\' WHEN ( (NOT (LOWER(final_status) LIKE \'%cancel%\')) AND order_manifest_date IS NOT NULL AND COALESCE(order_manifest_date, GETDATE()) <= Target_dispatch ) THEN \'DISPATCHED ON TIME\' END) AS o2s_status, UPPER(CASE WHEN LOWER(final_status) LIKE \'%cancel%\' THEN \'CANCELLED\' WHEN NOT(LOWER(final_status) LIKE \'%cancel%\') AND order_delivered_date IS NULL THEN \'NOT DELIVERED\' ELSE \'DELIVERED\' END) AS delivery_status FROM speeds ) SELECT * FROM TIME_CATEGORIES;",
                    "transaction": true
